INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass jede Tabelle immer einen Primärschlüssel haben muss?', 2, '[{"text": "Nein", "correct": true, "because": "Empfohlen, aber nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Technisch optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept verbindet zwei Tabellen miteinander?', 3, '[{"text": "Fremdschlüssel", "correct": true, "because": "Verweist auf Primärschlüssel"}, {"text": "Index", "correct": false, "because": "Beschleunigt Abfragen"}, {"text": "Trigger", "correct": false, "because": "Automatisiert Aktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Datenbanksystem effizient?', 5, '[{"text": "Normalisierung", "correct": true, "because": "Reduziert Redundanzen"}, {"text": "Indizierung", "correct": true, "because": "Beschleunigt Abfragen"}, {"text": "Hohe Zeilenanzahl", "correct": false, "because": "Kein Effizienzfaktor"}, {"text": "Farbcodierte Tabellen", "correct": false, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SQL ist die Standardabfragesprache. b) Sie ersetzt NoSQL-Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, NoSQL ist Alternative"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung einer Datenstruktur?', 4, '[{"text": "Normalisierungsregeln", "correct": false, "because": "Vermeiden Redundanzen"}, {"text": "Schlüsselbeziehungen", "correct": false, "because": "Sichern Integrität"}, {"text": "Tabellenfarbe", "correct": true, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Fremdschlüssel immer eindeutig sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Kann mehrfach vorkommen"}, {"text": "Ja", "correct": false, "because": "Nur Primärschlüssel eindeutig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalisierungsstufe eliminiert transitive Abhängigkeiten?', 4, '[{"text": "3NF", "correct": true, "because": "Entfernt indirekte Abhängigkeiten"}, {"text": "1NF", "correct": false, "because": "Nur atomare Werte"}, {"text": "BCNF", "correct": false, "because": "Strengere Bedingungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Joins immer langsam sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Indizes verbessern Leistung"}, {"text": "Ja", "correct": false, "because": "Leistung optimierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Tabelle ohne Primärschlüssel unzulässig?', 2, '[{"text": "Nein", "correct": true, "because": "Technisch erlaubt"}, {"text": "Ja", "correct": false, "because": "Nur empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Befehle nutze ich für Beziehungen?', 5, '[{"text": "JOIN", "correct": true, "because": "Verknüpft Tabellen"}, {"text": "FOREIGN KEY", "correct": true, "because": "Definiert Beziehungen"}, {"text": "INSERT", "correct": false, "because": "Fügt Daten ein"}, {"text": "DROP", "correct": false, "because": "Löscht Objekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Optimierung einer Datenbank?', 4, '[{"text": "Indizes für häufige Abfragen", "correct": true, "because": "Verbessert Leistung"}, {"text": "Maximale Tabellenanzahl", "correct": false, "because": "Komplexität erhöht"}, {"text": "Bunte Visuals", "correct": false, "because": "Keine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Normalisierung reduziert Anomalien. b) Sie macht Abfragen immer schneller.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, kann komplexer sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine effiziente Datenbank?', 3, '[{"text": "Primärschlüssel", "correct": false, "because": "Fördern Eindeutigkeit"}, {"text": "Indizes", "correct": false, "because": "Beschleunigen Abfragen"}, {"text": "Tabellenbeschriftung", "correct": true, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine Beziehung zwischen Tabellen erstelle?', 4, '[{"text": "Fremdschlüssel definieren", "correct": true, "because": "Verknüpft Tabellen"}, {"text": "Nur JOIN schreiben", "correct": false, "because": "Nur Abfrage, keine Struktur"}, {"text": "Trigger setzen", "correct": false, "because": "Für Aktionen, nicht Beziehungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Normalisierung Speicher spart. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Reduziert Redundanzen"}, {"text": "Nein", "correct": false, "because": "Normalisierung spart Platz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sichert die Konsistenz von Beziehungen?', 4, '[{"text": "Referentielle Integrität", "correct": true, "because": "Gültige Verweise"}, {"text": "Denormalisierung", "correct": false, "because": "Erhöht Redundanzen"}, {"text": "Partitionierung", "correct": false, "because": "Für Performance"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Index immer notwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Abfragen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gut gestaltete Datenbank?', 5, '[{"text": "Schnelle Abfragen", "correct": true, "because": "Durch Indizes und Struktur"}, {"text": "Datenintegrität", "correct": true, "because": "Durch Schlüssel"}, {"text": "Bunte Diagramme", "correct": false, "because": "Nur Visualisierung"}, {"text": "Maximale Datenmenge", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abfrageoptimierung unwichtig?', 3, '[{"text": "Indizes", "correct": false, "because": "Verbessern Leistung"}, {"text": "WHERE-Bedingungen", "correct": false, "because": "Reduzieren Datenmenge"}, {"text": "Spaltennamen", "correct": true, "because": "Kein Performancefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Daten aus zwei Tabellen verbinden will?', 4, '[{"text": "JOIN mit Fremdschlüssel", "correct": true, "because": "Verknüpft effizient"}, {"text": "Nur INSERT nutzen", "correct": false, "because": "Fügt Daten ein"}, {"text": "Trigger einrichten", "correct": false, "because": "Für Aktionen, nicht Abfragen"}]');
